/* CJAJLK Nature — V1 locale autonome. Aucun envoi de données. */
(()=>{'use strict';
const DB=window.NATURE_DATA, KEY='cjajlk-nature-v1-local';
const glyph={leaf:'<path d="M20 4c-9 0-15 5-15 12a4 4 0 0 0 4 4c7 0 12-6 11-16Z"/><path d="M4 21c4-7 8-10 13-12"/>',home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',book:'<path d="M12 6a8 8 0 0 0-9-1v14a8 8 0 0 1 9 1 8 8 0 0 1 9-1V5a8 8 0 0 0-9 1Z"/><path d="M12 6v14"/>',flask:'<path d="M9 3h6M10 3v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3"/><path d="M7 16h10"/>',box:'<path d="m12 2 9 5-9 5-9-5zM3 7v10l9 5 9-5V7M12 12v10"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 5v1"/>',settings:'<path d="M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1M18.4 5.6l-2.1 2.1m-8.6 8.6-2.1 2.1"/><circle cx="12" cy="12" r="4"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="M19 12H5m6 6-6-6 6-6"/>',check:'<path d="m4 12 5 5L20 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',drop:'<path d="M12 2c-4 6-8 10-8 14a8 8 0 0 0 16 0c0-4-4-8-8-14Z"/>',shirt:'<path d="m8 3-5 3-2 6 5 2 1-3v10h10V11l1 3 5-2-2-6-5-3a4 4 0 0 1-8 0Z"/>',sparkles:'<path d="m12 2 2 7 7 3-7 2-2 8-2-8-7-2 7-3z"/>',warning:'<path d="M10 4 2 19a2 2 0 0 0 2 3h16a2 2 0 0 0 2-3L14 4a2 2 0 0 0-4 0Z"/><path d="M12 10v5m0 3v.2"/>',shield:'<path d="M12 2 4 5v6c0 6 3 9 8 11 5-2 8-5 8-11V5z"/><path d="m9 12 2 2 4-4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',wallet:'<rect x="2" y="5" width="20" height="15" rx="3"/><path d="M2 9h20m-5 6h2"/>',trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6m5 4v7m4-7v7"/>',bookmark:'<path d="M6 3h12v19l-6-4-6 4z"/>',edit:'<path d="m3 17 1 4 4-1L20 8l-4-4L3 17Z"/><path d="m14 6 4 4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 21V9m-5 5 5-5 5 5M4 7V3h16v4"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h.1M3 12h.1M3 19h.1"/>',shopping:'<path d="m3 4 2 2 3 12h12l2-9H6"/><circle cx="10" cy="21" r="1"/><circle cx="18" cy="21" r="1"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',floor:'<path d="M4 5h16v14H4zM4 12h16M11 5v7m6 0v7M8 12v7"/>',spray:'<path d="M10 5h7l3 2v3h-3l-2-2h-5M9 5V3h4M8 10h9l2 11H6l2-11ZM4 9l-2 1"/>',window:'<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M12 3v18M4 12h16"/>',bowl:'<path d="M3 12h18c0 5-4 9-9 9S3 17 3 12ZM5 8h14M9 3v2m6-2v2"/>',jar:'<rect x="5" y="7" width="14" height="15" rx="3"/><path d="M4 4h16v3H4zM9 12h6"/>',dish:'<ellipse cx="12" cy="14" rx="9" ry="7"/><path d="M6 14c1-3 11-3 12 0M12 7V3"/>',laundry:'<rect x="3" y="2" width="18" height="20" rx="2"/><circle cx="12" cy="14" r="5"/><path d="M6 6h1m3 0h1"/>',cream:'<path d="M5 9h14l-1 12H6L5 9ZM8 5h8v4M9 3h6"/>',lip:'<path d="M9 3h6v8H9zM8 11h8v10H8zM9 15h6"/>',bottle:'<path d="M9 3h6v4H9zM7 7h10v14H7zM10 11h4v6h-4z"/>',shower:'<path d="M5 19V8a5 5 0 0 1 10 0v1m-4 0h8v3h-8zM12 16v1m4-1v1m4-1v1"/>',shampoo:'<path d="M9 2h6v5H9zM8 7h8l3 14H5zM8 12h8"/>',tooth:'<path d="M7 3c-5 1-5 6-3 10l3 8c2 2 3-4 5-8 2 4 3 10 5 8l3-8c2-4 2-9-3-10-3-1-4 1-5 1s-2-2-5-1Z"/>',sun:'<circle cx="12" cy="12" r="5"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M20 4l-2 2M6 18l-2 2"/>'};
const icon=(n,cls='')=>`<span class="icon ${cls}" aria-hidden="true"><svg viewBox="0 0 24 24">${glyph[n]||glyph.leaf}</svg></span>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const norm=x=>String(x??'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const money=x=>(Number(x)||0).toLocaleString('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:2});
const fmt=x=>(Number(x)||0).toLocaleString('fr-FR',{maximumFractionDigits:1});
const day=x=>new Date(x).toLocaleDateString('fr-FR',{day:'2-digit',month:'short',year:'numeric'});
const defaultState=()=>({version:1,profiles:[],activeProfileId:null,mode:'guide',favorites:[],inventory:{},prices:{},batches:[],comparisons:{}});
let state=defaultState();
try{const found=JSON.parse(localStorage.getItem(KEY)||'null');if(found&&found.version===1)state={...defaultState(),...found};}catch(e){console.warn('Sauvegarde locale invalide',e)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){toast('Sauvegarde impossible : stockage du navigateur indisponible.')}}
const categories=[['all','Tout voir','book'],['soins','Beauté & soins','sparkles'],['hygiene','Hygiène','drop'],['linge','Lessive & linge','shirt'],['maison','Entretien maison','home']];
let ui={page:'home',category:'all',search:'',owned:false,favoritesOnly:false,selectedId:null,quantity:null,step:0,safeChecked:false,productsTab:'stock',recipeSavedReturn:'recipes',sourceTab:'all',guideSearch:''};
const ing=id=>DB.ingredients.find(x=>x.id===id);
const recipe=id=>DB.recipes.find(x=>x.id===id);
const active=()=>state.profiles.find(x=>x.id===state.activeProfileId)||null;
const recipeCost=(r,scale=1)=>r.ingredients?r.ingredients.reduce((s,[id,qty])=>{const v=ing(id);if(!v)return s;const price=Number(state.prices[id]??v.price);return s+qty*scale/v.pack*(Number.isFinite(price)?Math.max(0,price):0)},0):0;
const pricePack=id=>{const a=ing(id);return Number(state.prices[id]??a.price)};
const stock=id=>Number(state.inventory[id]||0);
const scaleFor=r=>r?.type==='recette'&&ui.quantity?Number(ui.quantity)/r.base:1;
const missing=r=>r.ingredients?.filter(([id,n])=>stock(id)+.001<n*scaleFor(r))||[];
const allOwned=r=>r.type==='recette'&&r.ingredients.every(([id,n])=>stock(id)+.001>=n);
function profileRisk(r){const p=active();if(!['skin','laundry'].includes(r.sensitivity))return {level:'none',txt:''};if(!p)return r.sensitivity==='skin'?{level:'setup',txt:'Créez un profil avant toute fabrication de soin.'}:{level:'none',txt:''};const allerg=norm(p.allergies).split(/[,;\n\/]+/).map(x=>x.trim()).filter(x=>x.length>=3&& !['aucune','aucun','non','rien','inconnue','inconnu'].includes(x));const hit=(r.ingredients||[]).map(([id])=>ing(id).name).filter(name=>allerg.some(a=>norm(name).includes(a)));if(hit.length)return{level:'stop',txt:`Allergie ou sensibilité déclarée pouvant concerner : ${hit.join(', ')}. Ne pas utiliser cette recette sans avis adapté.`};const issues=p.issues||[];if(r.sensitivity==='laundry'&&(issues.length||p.skin==='sensible'))return{level:'caution',txt:'Peau sensible : essayer d’abord une petite charge de linge, bien rincer et surveiller d’éventuelles irritations. Ne pas appliquer la lessive concentrée sur la peau.'};if(issues.includes('eczema')||issues.includes('psoriasis')||issues.includes('lesion'))return{level:'caution',txt:'Profil signalant un trouble cutané : ne pas utiliser sur peau lésée ou en poussée ; demander conseil à un professionnel avant de tester.'};if(issues.length||p.skin==='sensible')return{level:'caution',txt:'Peau sensible : vérifier attentivement les ingrédients et demander conseil en cas de doute.'};return{level:'ok',txt:'Aucune incompatibilité détectée à partir de vos déclarations. Cela ne garantit pas l’absence de réaction.'};}
function personalizedAdvice(r){const p=active();if(!p)return '';if(r.category==='hygiene'&&r.id==='shampoing'&&p.hair==='sensibles')return 'Cuir chevelu sensible déclaré : choisir une formule douce sans parfum, avec conseil professionnel en cas de lésions.';if(r.sensitivity!=='skin'||r.type==='guide')return '';const advice={'sèche':'Peau sèche déclarée : un soin gras peut être confortable mais peut également irriter ; testez prudemment sur peau saine.','grasse':'Peau grasse déclarée : prudence avec les préparations grasses, particulièrement près du visage ou de zones acnéiques.','mixte':'Peau mixte déclarée : éviter d’appliquer un baume riche sur les zones grasses du visage.','sensible':'Peau sensible déclarée : n’essayez pas de préparation sur peau irritée ou lésée.','normale':'Même sur peau normale, une réaction cutanée reste possible.'};return advice[p.skin]||'Type de peau non défini : vérifiez les ingrédients et les précautions.'}
function navButton(page,label,symbol,cls='nav-item'){return `<button class="${cls} ${ui.page===page||(page==='recipes'&&(ui.page==='detail'||ui.page==='guides'))?'active':''}" type="button" data-action="go" data-page="${page}">${icon(symbol)}<span>${label}</span></button>`}
function header(){const p=active();const mark=`<div class="brand-icon">${icon('leaf','lg')}</div><div><div class="brand-name">CJAJLK Nature</div><div class="brand-tag">LE NATUREL AU QUOTIDIEN</div></div>`;return `<aside class="sidebar"><div class="brand">${mark}</div><nav class="side-nav" aria-label="Navigation principale">${navButton('home','Accueil','home')}${navButton('recipes','Recettes','book')}${navButton('fabricate','Fabriquer','flask')}${navButton('products','Mes produits','box')}${navButton('profiles','Profils','users')}</nav><div class="side-bottom"><div class="aside-note">${icon('shield')}<strong> Le naturel, avec prudence.</strong><p>Des ingrédients simples, des dosages clairs et des avertissements visibles à chaque étape.</p></div><button class="aside-link" data-action="go" data-page="settings">${icon('settings','sm')} Réglages & sources</button><div class="subtle" style="font-size:10px;padding:10px">V1.4 · Données enregistrées sur cet appareil</div></div></aside><main class="content"><header class="topbar"><div class="mobile-brand brand">${mark}</div><div class="topright"><span class="pill small">${icon('leaf','sm')} <span>Recettes sans parfum ajouté</span></span><button class="small-button profile-chip" data-action="go" data-page="profiles" aria-label="Ouvrir les profils">${icon('users','sm')} <span>${esc(p?.name||'Créer profil')}</span></button><button class="small-button" data-action="go" data-page="settings" aria-label="Réglages">${icon('settings','sm')}</button></div></header>`;}
function bottom(){return `</main><nav class="mobile-nav" aria-label="Navigation mobile">${navButton('home','Accueil','home','mobile-item')}${navButton('recipes','Recettes','book','mobile-item')}${navButton('fabricate','Fabriquer','flask','mobile-item')}${navButton('products','Mes produits','box','mobile-item')}${navButton('profiles','Profils','users','mobile-item')}</nav>`;}
function heroArt(){return `<svg viewBox="0 0 330 285" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><linearGradient id="glass" x1="0" x2="1"><stop stop-color="#95c0bf" stop-opacity=".55"/><stop offset=".55" stop-color="#bce7e7" stop-opacity=".2"/><stop offset="1" stop-color="#4d8793" stop-opacity=".6"/></linearGradient><linearGradient id="amber" x1="0" x2="1"><stop stop-color="#cc9c59"/><stop offset=".5" stop-color="#855d36"/><stop offset="1" stop-color="#dfad65"/></linearGradient><linearGradient id="cream" x1="0" x2="1"><stop stop-color="#f3e9c8"/><stop offset="1" stop-color="#c2d3e2"/></linearGradient></defs><ellipse cx="178" cy="261" rx="148" ry="19" fill="#071522" opacity=".5"/><path d="M70 234c-29-63-17-139 30-184 5 51 13 68 27 94-9-54 19-103 57-130 11 80-24 148-66 216" fill="#667f89" opacity=".48"/><path d="M203 233c10-64 55-134 101-158-9 67-34 104-69 151" fill="#79909d" opacity=".38"/><path d="M100 246C79 203 60 186 36 172c5 45 17 62 48 79" fill="#9eb2ba" opacity=".35"/><rect x="141" y="65" width="92" height="185" rx="23" fill="url(#amber)" stroke="#eec98a" stroke-opacity=".45" stroke-width="2"/><rect x="167" y="43" width="39" height="28" rx="4" fill="#b79768"/><rect x="171" y="28" width="32" height="18" rx="4" fill="#d6d8b2"/><path d="M187 29V13h56" stroke="#e0e6c7" stroke-width="9" stroke-linecap="round"/><path d="M247 13v14" stroke="#e0e6c7" stroke-width="6" stroke-linecap="round"/><rect x="149" y="124" width="76" height="79" rx="8" fill="url(#cream)"/><path d="M178 154c-3-16 6-24 22-27-3 15-10 27-22 27Z" fill="#4e8996"/><path d="M181 151c3 12 9 20 18 25" stroke="#4e8996" stroke-width="2" fill="none"/><text x="187" y="184" font-size="8" font-family="sans-serif" text-anchor="middle" font-weight="bold" fill="#466b7e">NATURE</text><rect x="62" y="146" width="86" height="105" rx="14" fill="url(#glass)" stroke="#a9ced1" stroke-opacity=".45" stroke-width="2"/><rect x="70" y="137" width="69" height="15" rx="4" fill="#d9d3b4"/><rect x="78" y="175" width="55" height="47" rx="5" fill="#e0e7d0" opacity=".85"/><path d="M104 188c-7-8-6-14 5-21 5 12 0 18-5 21Z" fill="#639ba0"/><text x="106" y="206" font-size="8" font-family="sans-serif" font-weight="bold" fill="#648c9c" text-anchor="middle">SOIN</text><circle cx="278" cy="221" r="31" fill="#d6c7a0" opacity=".7"/><path d="M278 200c-12 6-13 21 0 37 13-16 12-31 0-37Z" fill="#739da2"/></svg>`;}
function recipeCard(r){const guide=r.type==='guide',risk=profileRisk(r);const cost=guide?'Conseils & sécurité':`Dès ${money(recipeCost(r))}*`;return `<button class="recipe-card" type="button" data-action="open-recipe" data-id="${r.id}" data-category="${r.category}" data-search="${esc(norm([r.title,r.desc,r.category,...(r.tags||[])].join(' ')))}" data-owned="${allOwned(r)}"><div class="recipe-image ${r.category}">${icon(r.icon)}</div><div class="recipe-card-body"><div class="badge-list">${guide?'<span class="tag guide">Guide</span>':`<span class="tag">${esc(r.level)}</span>`}${(r.tags||[]).slice(0,1).map(t=>`<span class="tag ${t==='Recette pilote'?'conditional':''}">${esc(t)}</span>`).join('')}</div><div class="recipe-card-title">${esc(r.title)}</div><p class="recipe-card-desc">${esc(r.desc)}</p><div class="meta-row"><span>${esc(cost)}</span><span>${icon(guide?'info':'clock','sm')} ${guide?'À lire':r.minutes+' min'}</span></div>${risk.level==='stop'?'<span class="tag conditional">Allergie à vérifier</span>':''}</div></button>`;}
const catIcon={soins:'sparkles',hygiene:'drop',linge:'shirt',maison:'home'};
function home(){const p=active();const n=state.batches.length;const spent=state.batches.reduce((s,b)=>s+b.cost,0);const saved=state.batches.reduce((s,b)=>s+(b.comparison!=null?b.comparison-b.cost:0),0);return `<section class="hero"><div class="hero-copy"><span class="eyebrow">VOTRE ATELIER AU NATUREL</span><h1>Des gestes simples.<br>Un quotidien <span style="color:#B7AAFF">plus doux.</span></h1><p>Fabriquez, comparez les coûts et prenez soin de votre maison avec des ingrédients simples et des précautions claires.</p><div class="btn-row"><button class="btn btn-primary" data-action="go" data-page="recipes">Explorer les recettes ${icon('arrow','sm')}</button><button class="btn btn-secondary" data-action="go" data-page="fabricate">Fabriquer</button></div></div><div class="hero-art">${heroArt()}</div></section>
 ${!p?`<div class="feature" style="margin-bottom:20px"><div class="feature-icon">${icon('users','lg')}</div><div style="flex:1"><h3>Une application adaptée à votre famille</h3><p>Avant les soins pour la peau, créez votre profil : type de peau, eczéma, allergies et préférences.</p><button class="btn tiny btn-primary" style="margin-top:12px" data-action="profile-modal">Créer mon profil</button></div></div>`:p.issues?.length?`<div class="safety" style="margin-bottom:20px"><h3>${icon('shield')} Profil ${esc(p.name)} : vigilance cutanée</h3><div style="font-size:12px">Les soins proposés ne sont pas des traitements. Ne pas utiliser de recettes sur une peau lésée ou lors d’une poussée d’eczéma ; demander conseil à un professionnel.</div></div>`:''}
 <div class="section-heading"><h2>Que souhaitez-vous fabriquer ?</h2></div><div class="categories">${categories.slice(1).map(([id,label,sym])=>`<button class="category-card" data-action="go-category" data-category="${id}">${icon(sym,'lg')}<strong>${label}</strong><small>${DB.recipes.filter(r=>r.category===id&&r.type==='recette').length} recettes</small></button>`).join('')}</div>
 <div class="feature guide-entry" style="margin-top:18px;margin-bottom:16px"><div class="feature-icon">${icon('shield','lg')}</div><div style="flex:1"><h3>Conseils & sécurité</h3><p>Protection solaire, shampoings, dentifrices : comprendre pourquoi certaines préparations maison ne sont pas proposées.</p><button class="btn tiny btn-secondary" style="margin-top:10px" data-action="go" data-page="guides">Lire les guides ${icon('arrow','sm')}</button></div></div>
 <div class="section-heading"><h2>À découvrir</h2><button class="text-link" data-action="go" data-page="recipes">Voir tout ${icon('arrow','sm')}</button></div><div class="recipe-grid">${['lessive','baume','sols'].map(id=>recipeCard(recipe(id))).join('')}</div>
 <div class="section-heading"><h2>Votre atelier en chiffres</h2></div><div class="dashboard-cards"><div class="feature"><div class="feature-icon">${icon('wallet','lg')}</div><div style="flex:1"><h3>Mes économies</h3><p>Vos comparaisons sont calculées uniquement quand vous renseignez un prix réel du commerce.</p><div class="metrics"><div class="metric"><div class="value">${money(saved)}</div><div class="label">Économies estimées*</div></div><div class="metric"><div class="value">${n}</div><div class="label">Fabrications suivies</div></div></div></div></div><div class="feature"><div class="feature-icon">${icon('leaf','lg')}</div><div><h3>Mes ingrédients</h3><p>${DB.ingredients.filter(a=>stock(a.id)>0).length} ingrédient(s) actuellement en stock. Ajoutez vos quantités pour voir les recettes réalisables.</p><button class="btn tiny btn-secondary" style="margin-top:15px" data-action="go" data-page="products">Gérer mon placard ${icon('arrow','sm')}</button></div></div></div><p class="help">*Coûts de recettes estimés selon des prix d’exemple modifiables. Aucune économie n’est supposée sans comparaison réelle.</p>`;}
function recipes(){const real=DB.recipes.filter(r=>r.type==='recette');const rs=real.filter(r=>ui.category==='all'||r.category===ui.category);return `<div class="page-title"><div><span class="eyebrow">LE CARNET DE L'ATELIER</span><h1>Les recettes</h1><p>Uniquement des préparations réalisables, avec ingrédients, matériel, précautions et coûts indicatifs.</p></div><span class="pill small">${real.length} recettes</span></div>
 <div class="guide-entry compact-guide"><div>${icon('shield','sm')} <b>Conseils & sécurité</b><p>Les fiches informatives ne sont plus mélangées aux recettes.</p></div><button class="btn tiny btn-secondary" data-action="go" data-page="guides">Voir les ${DB.recipes.filter(r=>r.type==='guide').length} guides ${icon('arrow','sm')}</button></div>
 <label class="search-area">${icon('search')}<input id="catalog-search" type="search" placeholder="Rechercher : lessive, soin, vitres..." aria-label="Rechercher les recettes" value="${esc(ui.search)}"></label><div class="filters">${categories.map(([id,name])=>`<button class="chip ${ui.category===id?'active':''}" data-action="filter" data-category="${id}">${name}</button>`).join('')}<button class="chip ${ui.owned?'active':''}" data-action="toggle-owned">${icon('check','sm')} Avec mon placard</button><button class="chip ${ui.favoritesOnly?'active':''}" data-action="toggle-favorites-filter">${icon('bookmark','sm')} Mes favoris</button></div><p class="muted" id="results-count" style="font-size:12px;margin-bottom:13px"></p><div class="recipe-grid" id="catalog-grid">${rs.map(recipeCard).join('')}</div><div id="guide-search-suggestion" class="guide-entry guide-suggestion hide"></div><div id="catalog-empty" class="empty hide">Aucune recette ne correspond à votre recherche. Modifiez les filtres ou consultez les guides de précaution.</div>`;}
function guides(){const gs=DB.recipes.filter(r=>r.type==='guide');return `<div class="page-title"><div><span class="eyebrow">INFORMATION ET PRÉVENTION</span><h1>Conseils & sécurité</h1><p>Pourquoi certaines préparations ne sont pas proposées, et quelles solutions privilégier.</p></div><span class="pill small">${gs.length} guides</span></div><button class="back" data-action="go" data-page="recipes">${icon('back','sm')} Retour aux recettes</button><div class="guide-entry compact-guide"><div>${icon('shield','sm')} <b>Les guides ne sont pas des recettes</b><p>Aucun ingrédient à peser ni produit à fabriquer ici. Ce sont des informations de prudence.</p></div></div><label class="search-area">${icon('search')}<input type="search" id="guide-search" value="${esc(ui.guideSearch)}" placeholder="Chercher : solaire, déodorant, shampoing..." aria-label="Rechercher les guides"></label><p class="muted" id="guides-count" style="font-size:12px;margin-bottom:13px"></p><div id="guide-grid" class="recipe-grid">${gs.map(recipeCard).join('')}</div><div id="guides-empty" class="empty hide">Aucun guide ne correspond à la recherche.</div>`;}
function filterGuideCards(){const cards=[...document.querySelectorAll('#guide-grid .recipe-card')];let n=0;cards.forEach(card=>{const r=recipe(card.dataset.id);const ok=norm([r.title,r.desc,r.category,...(r.tags||[])].join(' ')).includes(norm(ui.guideSearch));card.classList.toggle('hide',!ok);if(ok)n++;});const el=document.getElementById('guides-count');if(el)el.textContent=n+' guide'+(n>1?'s':'')+' affiché'+(n>1?'s':'');document.getElementById('guides-empty')?.classList.toggle('hide',n>0);}
function safetyBox(r, risk){const arr=[...r.safety];return `<div class="safety ${risk.level==='stop'?'red':''}"><h3>${icon('warning','sm')} ${risk.level==='stop'?'Incompatibilité possible':'Précautions indispensables'}</h3>${risk.level!=='none'?`<p style="font-size:12px;font-weight:750;margin-bottom:11px">${esc(risk.txt)}</p>`:''}<ul>${arr.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`;}
function sourcesLinks(r){return r.source.map(id=>DB.sources.find(x=>x.id===id)).filter(Boolean).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a>`).join('');}
function ingredientsList(r,scale){const rows=r.ingredients.map(([id,qty])=>{const a=ing(id),required=qty*scale,available=stock(id),ok=available+.001>=required;return `<tr><td><b>${esc(a.name)}</b><br><small class="muted">Placard : ${fmt(available)} ${a.unit} ${ok?'✓':'· manque '+fmt(Math.max(0,required-available))+' '+a.unit}</small></td><td>${fmt(required)} ${a.unit}</td></tr>`;});return `<table class="table-ingredients"><thead><tr><th>Ingrédient</th><th>Quantité</th></tr></thead><tbody>${rows.join('')}</tbody></table>`}
function equipmentPanel(r){
 const eq=r.equipment;if(!eq)return '';
 const lines=arr=>arr.map(x=>`<li>${icon('check','sm')}<span>${esc(x)}</span></li>`).join('');
 return `<div class="panel equipment-panel" style="margin-top:15px">
 <div class="panel-header"><h3>${icon('box','sm')} Matériel à prévoir</h3><span class="pill small">Avant de commencer</span></div>
 <p class="muted equipment-intro">Voici les ustensiles et contenants utiles pour cette recette. Inutile d’acheter du matériel si vous avez déjà un équivalent adapté, propre et sûr.</p>
 <div class="equipment-grid"><section class="equipment-group"><h4>Indispensable</h4><ul class="equipment-list">${lines(eq.essential||[])}</ul></section>
 ${(eq.optional||[]).length?`<section class="equipment-group optional"><h4>Facultatif / pratique</h4><ul class="equipment-list">${lines(eq.optional)}</ul></section>`:''}</div>
 <div class="equipment-container"><b>${icon('jar','sm')} Contenant et rangement</b><p>${esc(eq.container)}</p></div>
 ${eq.note?`<div class="equipment-caution">${icon('info','sm')}<span>${esc(eq.note)}</span></div>`:''}
 <div class="btn-row"><button class="btn tiny btn-secondary" data-action="copy-equipment">${icon('shopping','sm')} Copier la liste du matériel</button></div>
 <small class="field-helper">Le coût affiché pour une recette porte sur les ingrédients, pas sur l’achat de ce matériel.</small>
 </div>`;
}
function stepText(r,raw){const sc=scaleFor(r);return String(raw).replace(/\{\{([a-z_]+)\}\}/g,(m,id)=>{const row=r.ingredients.find(x=>x[0]===id),a=ing(id);return row&&a?fmt(row[1]*sc)+' '+a.unit:m;});}
function stepsContent(r){const total=r.steps.length,step=Math.max(0,Math.min(total-1,ui.step));if(state.mode==='guide')return `<div class="step-hero"><div class="step-num">Étape ${step+1} sur ${total}</div><div class="step-text">${esc(stepText(r,r.steps[step]))}</div><div class="progress"><div style="width:${(step+1)/total*100}%"></div></div></div><div class="make-actions"><button class="btn btn-secondary" data-action="step-prev" ${step===0?'disabled':''}>${icon('back','sm')} Précédent</button>${step<total-1?`<button class="btn btn-primary" data-action="step-next">Suivant ${icon('arrow','sm')}</button>`:`<button class="btn btn-primary" data-action="finish">${icon('check','sm')} Terminer la fabrication</button>`}</div>`;return `<ol class="steps">${r.steps.map((st,i)=>`<li><span class="step-bubble">${i+1}</span><span>${esc(stepText(r,st))}</span></li>`).join('')}</ol><div class="make-actions"><button class="btn btn-primary" data-action="finish">${icon('check','sm')} Terminer la fabrication</button></div>`;}
function detail(){const r=recipe(ui.selectedId);if(!r)return recipes();const risk=profileRisk(r),isGuide=r.type==='guide',scale=scaleFor(r),qty=ui.quantity||r.base;return `<button class="back" data-action="go" data-page="${isGuide?'guides':'recipes'}">${icon('back','sm')} ${isGuide?'Retour aux conseils':'Retour aux recettes'}</button><div class="detail-head"><div><span class="eyebrow">${esc(categories.find(c=>c[0]===r.category)?.[1]||'Atelier')}</span><h1 style="margin-top:8px">${esc(r.title)}</h1><p>${esc(r.desc)}</p><div class="badge-list" style="margin-top:14px">${isGuide?'<span class="tag guide">Guide de précaution</span>':`<span class="tag">${esc(r.level)}</span><span class="tag">${r.minutes} min environ</span>`}${(r.tags||[]).map(t=>`<span class="tag pale">${esc(t)}</span>`).join('')}</div></div><div class="detail-art">${icon(r.icon)}</div></div><div class="detail-layout"><div>${isGuide?`<div class="guide-note"><div class="eyebrow" style="margin-bottom:9px">INFORMATION & CONSEILS</div>${esc(r.guide)}</div>`:`<div class="panel"><div class="panel-header"><h3>${icon('flask','sm')} Votre fabrication</h3><span class="pill small">${fmt(qty)} ${r.yieldUnit}</span></div><div class="field"><label for="recipe-qty">Quantité à préparer (${r.yieldUnit})</label><div class="amount-row"><input id="recipe-qty" type="number" min="1" max="50000" step="1" value="${qty}"><button class="small-button" data-action="set-quantity" data-factor="0.5">½</button><button class="small-button" data-action="set-quantity" data-factor="1">×1</button><button class="small-button" data-action="set-quantity" data-factor="2">×2</button></div><small class="field-helper">Les doses du tableau et celles des étapes se recalculent ensemble. Adaptez le volume du récipient et du matériel au besoin.</small></div>${ingredientsList(r,scale)}<div class="divider"></div><div class="panel-header"><div><span class="eyebrow">COÛT ESTIMÉ DES INGRÉDIENTS</span><div class="cost-value">${money(recipeCost(r,scale))}</div><div class="cost-caption">Prix indicatifs, modifiables dans « Mes produits » ; emballage/énergie non compris.</div></div></div><div class="btn-row" style="margin-top:15px"><button class="btn tiny btn-ghost" data-action="copy-shopping">${icon('shopping','sm')} Copier les ingrédients manquants</button><button class="btn tiny btn-secondary" data-action="go" data-page="products">${icon('edit','sm')} Ajuster mes prix</button></div></div>`}
 ${!isGuide?equipmentPanel(r):''}
 <div class="panel" style="margin-top:15px"><h3>${icon('shield','sm')} Sécurité avant utilisation</h3>${safetyBox(r,risk)}${personalizedAdvice(r)?`<div class="status-note" style="margin-top:12px"><b>Conseil pour ${esc(active()?.name||'votre profil')} :</b> ${esc(personalizedAdvice(r))}</div>`:''}<div class="status-note" style="margin-top:12px"><b>Conservation :</b> ${esc(isGuide?'Consulter la notice du produit du commerce.':r.storage)}</div></div>${!isGuide?`<div class="panel" style="margin-top:15px"><div class="panel-header"><h3>${icon('list','sm')} Fabriquer votre produit</h3><span class="pill small">${state.mode==='guide'?'Guidé':'Fiche complète'}</span></div><div class="switcher" role="group" aria-label="Mode de fabrication"><button class="${state.mode==='guide'?'active':''}" data-action="choose-mode" data-mode="guide">${icon('arrow','sm')} Pas à pas</button><button class="${state.mode==='fiche'?'active':''}" data-action="choose-mode" data-mode="fiche">${icon('list','sm')} Fiche complète</button></div>${risk.level==='stop'?`<div class="safety red"><h3>${icon('warning','sm')} Fabrication bloquée</h3>Une allergie déclarée peut correspondre à un ingrédient de cette recette. Cette V1 bloque son lancement par précaution.</div>`:risk.level==='setup'?`<div class="status-note">Renseignez un profil avant de fabriquer un produit destiné à la peau.</div><button style="margin-top:12px" class="btn btn-primary" data-action="profile-modal">${icon('users','sm')} Créer mon profil</button>`:`<label class="checkline"><input id="safety-check" type="checkbox" ${ui.safeChecked?'checked':''}><span>J’ai lu les précautions, vérifié les ingrédients et je respecterai les limites de cette recette.</span></label><div id="make-steps">${ui.safeChecked?stepsContent(r):'<div class="status-note">Cochez la confirmation pour accéder aux étapes de fabrication.</div>'}</div>`}</div>`:''}</div>
 <div><div class="panel slim"><h3>${icon('info','sm')} À savoir</h3><p class="muted" style="font-size:12px">${isGuide?'Cette fiche est informative et ne propose pas de préparation artisanale.':'Recette pilote pour usage domestique, non certifiée en laboratoire. Adaptez uniquement la quantité, pas la composition.'}</p><div class="divider"></div><h3>Sources utiles</h3><div class="source-links">${sourcesLinks(r)}</div></div><div class="panel slim" style="margin-top:15px"><h3>${icon('bookmark','sm')} Mes favoris</h3><button class="btn btn-secondary wide" data-action="toggle-fav" data-id="${r.id}">${icon('bookmark','sm')} ${state.favorites.includes(r.id)?'Retirer des favoris':'Ajouter aux favoris'}</button></div></div></div>`;}
function fabricate(){const r=recipe(ui.selectedId);return `<div class="page-title"><div><span class="eyebrow">VOTRE ÉTABLI</span><h1>Fabriquer</h1><p>${r&&r.type==='recette'?'La recette est prête à être suivie.':'Choisissez une recette pour démarrer votre fabrication.'}</p></div></div>${r&&r.type==='recette'?`<div class="feature" style="margin-bottom:19px"><div class="feature-icon">${icon(r.icon)}</div><div style="flex:1"><h3>${esc(r.title)}</h3><p>Deux modes disponibles : guidage pas à pas ou fiche complète. Votre choix est mémorisé.</p><button class="btn btn-primary tiny" data-action="go-detail" data-id="${r.id}" style="margin-top:12px">Ouvrir la fabrication ${icon('arrow','sm')}</button></div></div>`:''}<div class="section-heading"><h2>Choisir un produit</h2></div><div class="recipe-grid">${DB.recipes.filter(x=>x.type==='recette').map(recipeCard).join('')}</div>`;}
function productView(){const n=DB.ingredients.filter(a=>stock(a.id)>0).length,total=state.batches.length;const totalCost=state.batches.reduce((s,b)=>s+b.cost,0);const savings=state.batches.filter(b=>b.comparison!=null).reduce((s,b)=>s+(b.comparison-b.cost),0);
return `<div class="page-title"><div><span class="eyebrow">VOTRE ATELIER PERSONNEL</span><h1>Mes produits</h1><p>Votre placard, vos prix réels et vos fabrications.</p></div></div><div class="purchase-ethics" role="note" aria-label="Notre engagement sur le choix des magasins"><div class="purchase-ethics-title">${icon('shield','sm')} Achats libres, conseils indépendants</div><p><strong>CJAJLK Nature ne perçoit aucune commission</strong> sur vos achats et ne propose aucun placement de magasin rémunéré. <strong>Aucun vendeur n’est imposé</strong> : vous restez libre de choisir le magasin, le site ou le producteur que vous préférez.</p><p class="purchase-ethics-sub">La future rubrique « Où acheter ? » présentera des options à titre informatif, avec des critères transparents (prix, quantité, qualité et disponibilité), jamais des recommandations payées. Les achats se feront hors de l’application.</p></div><div class="kpi-row"><div class="kpi"><strong>${n}</strong><small>Ingrédients en stock</small></div><div class="kpi"><strong>${total}</strong><small>Fabrications</small></div><div class="kpi"><strong>${money(totalCost)}</strong><small>Coût fabriqué estimé</small></div></div><div class="subnav"><button class="chip ${ui.productsTab==='stock'?'active':''}" data-action="products-tab" data-tab="stock">${icon('box','sm')} Mon placard</button><button class="chip ${ui.productsTab==='history'?'active':''}" data-action="products-tab" data-tab="history">${icon('calendar','sm')} Fabrications</button><button class="chip ${ui.productsTab==='savings'?'active':''}" data-action="products-tab" data-tab="savings">${icon('wallet','sm')} Économies</button></div>${ui.productsTab==='stock'?`<div class="section-heading"><h2>Ingrédients et prix</h2></div><p class="muted" style="margin-bottom:17px;font-size:12px">Les prix affichés au départ sont des exemples, pas des prix du marché vérifiés. Saisissez vos vrais prix de paquet et quantités pour fiabiliser les calculs.</p><div class="stock-grid">${DB.ingredients.map(a=>`<div class="stock-item"><div class="title">${esc(a.name)}</div><div class="nums"><span>Stock : <span class="num">${fmt(stock(a.id))} ${a.unit}</span></span><span>Prix : <span class="num">${money(pricePack(a.id))} / ${a.pack} ${a.unit}</span></span></div><p class="purchase-hint">${esc(a.buyTip||'Choisissez un magasin de votre choix ; vérifier la qualité et les instructions.')}</p><button class="btn btn-secondary tiny" data-action="stock-modal" data-id="${a.id}">${icon('edit','sm')} Modifier</button></div>`).join('')}</div>`:ui.productsTab==='history'?`${state.batches.length?`<div class="profile-rows">${[...state.batches].reverse().map(b=>{const r=recipe(b.recipeId);return `<div class="mini-card"><div><h4>${esc(r?.title||'Recette supprimée')}</h4><small>${day(b.date)} · ${fmt(b.quantity)} ${esc(b.unit)} · ${money(b.cost)}${b.comparison!=null?' · Réf. commerce '+money(b.comparison):''}</small></div><button class="small-button" aria-label="Supprimer cette fabrication" data-action="delete-batch" data-id="${esc(b.id)}">${icon('trash','sm')}</button></div>`}).join('')}</div>`:`<div class="empty-state">${icon('calendar','lg')}<h3>Pas encore de fabrication</h3><p>Terminez une recette et enregistrez-la : elle apparaîtra ici avec son coût et sa date.</p><button class="btn btn-primary" data-action="go" data-page="fabricate">Choisir une recette</button></div>`}`:`<div class="panel"><h3>Comparaison de vos coûts</h3><div class="metrics"><div class="metric"><div class="value">${money(totalCost)}</div><div class="label">Coût total des ingrédients</div></div><div class="metric"><div class="value">${money(savings)}</div><div class="label">Écart commerce estimé</div></div></div><p class="help">L’écart peut être négatif. Il n’est calculé que pour les fabrications avec un prix de commerce réellement renseigné par vous. Il exclut le temps, l’énergie et l’emballage.</p></div>`}`;}
function profiles(){const p=active();return `<div class="page-title"><div><span class="eyebrow">ADAPTÉ À CHACUN</span><h1>Profils familiaux</h1><p>Peau, allergies, sensibilités et préférences de fabrication.</p></div><button class="btn btn-primary" data-action="profile-modal">${icon('plus','sm')} Ajouter un profil</button></div><div class="safety" style="margin-bottom:20px"><h3>${icon('shield','sm')} Confidentialité</h3><div style="font-size:12px">Ces informations de sensibilité cutanée sont enregistrées uniquement dans le stockage de ce navigateur, sur cet appareil. Elles ne sont pas envoyées à un serveur. Évitez les appareils partagés.</div></div>${!state.profiles.length?`<div class="empty-state">${icon('users','lg')}<h3>Créons votre premier profil</h3><p>Il permettra d'afficher les avertissements adaptés avant les soins de la peau.</p><button class="btn btn-primary" data-action="profile-modal">Commencer</button></div>`:`<div class="profile-rows">${state.profiles.map(x=>`<div class="profile-row ${p?.id===x.id?'active':''}"><div class="avatar">${esc((x.name||'?')[0].toUpperCase())}</div><div class="expand"><h3>${esc(x.name)}</h3><small class="muted">Peau : ${esc(x.skin||'non précisée')} · ${x.issues?.length?esc(x.issues.join(', ')):'aucune sensibilité déclarée'}</small><div class="badge-list" style="margin-top:7px">${p?.id===x.id?'<span class="tag">Profil actif</span>':''}${x.allergies?'<span class="tag conditional">Allergies déclarées</span>':''}</div></div><div class="mini-actions"><button class="small-button" data-action="select-profile" data-id="${x.id}" aria-label="Choisir ce profil" ${p?.id===x.id?'disabled':''}>${icon('check','sm')}</button><button class="small-button" data-action="profile-modal" data-id="${x.id}" aria-label="Modifier le profil">${icon('edit','sm')}</button><button class="small-button" data-action="delete-profile" data-id="${x.id}" aria-label="Supprimer le profil">${icon('trash','sm')}</button></div></div>`).join('')}</div>`}<p class="help">Les informations ne sont pas un diagnostic. Elles servent à signaler des risques, pas à certifier une recette « compatible » ou « sans allergène ».</p>`;}
function settings(){return `<div class="page-title"><div><span class="eyebrow">V1.5 — PARAMÈTRES</span><h1>Réglages & sources</h1><p>Vos données restent sur votre appareil.</p></div></div><div class="purchase-ethics" role="note" aria-label="Notre engagement sur le choix des magasins"><div class="purchase-ethics-title">${icon('shield','sm')} Achats libres, conseils indépendants</div><p><strong>CJAJLK Nature ne perçoit aucune commission</strong> sur vos achats et ne propose aucun placement de magasin rémunéré. <strong>Aucun vendeur n’est imposé</strong> : vous restez libre de choisir le magasin, le site ou le producteur que vous préférez.</p><p class="purchase-ethics-sub">La future rubrique « Où acheter ? » présentera des options à titre informatif, avec des critères transparents (prix, quantité, qualité et disponibilité), jamais des recommandations payées. Les achats se feront hors de l’application.</p></div><div class="panel"><h3>Mes données locales</h3><p class="muted">L'application ne nécessite ni compte ni serveur. Vous pouvez conserver une sauvegarde JSON de votre placard, de vos profils et de votre historique, ou la réimporter sur un autre appareil.</p><div class="btn-row" style="margin-top:17px"><button class="btn btn-secondary" data-action="export">${icon('download','sm')} Exporter mes données</button><button class="btn btn-ghost" data-action="import">${icon('upload','sm')} Importer une sauvegarde</button></div><input class="hide" type="file" accept="application/json,.json" id="import-input" aria-label="Fichier de sauvegarde JSON"><div class="divider"></div><h3>Mode de fabrication favori</h3><div class="switcher" style="margin-top:12px"><button data-action="choose-mode" data-mode="guide" class="${state.mode==='guide'?'active':''}">Pas à pas</button><button data-action="choose-mode" data-mode="fiche" class="${state.mode==='fiche'?'active':''}">Fiche complète</button></div><p class="help">Les deux modes utilisent la même recette et les mêmes consignes de sécurité.</p></div><div class="panel" style="margin-top:15px"><h3>Sources consultées</h3><p class="muted">Liens d'information et de prudence. Les recettes de soin sont des exemples de formulation artisanale, non certifiés par ces organismes.</p><div class="sources-list">${DB.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a>`).join('')}</div></div><div class="panel" style="margin-top:15px"><h3>À propos de la V1</h3><p class="muted">Cette version présente 46 recettes ou méthodes de préparation et une rubrique distincte de guides de précaution. Elle ne remplace pas l'avis d'un professionnel de santé, d'un fabricant de machine ou les consignes de sécurité des matières premières. Les prix initiaux sont indicatifs. Les recettes contenant de l'eau destinées à la peau ne sont pas proposées faute de validation microbiologique.</p><div class="divider"></div><button class="btn btn-danger" data-action="reset">${icon('trash','sm')} Effacer toutes mes données locales</button></div>`;}
function render(scroll=false){const views={home,recipes,guides,fabricate,products:productView,profiles,detail,settings};document.getElementById('app').innerHTML=header()+(views[ui.page]||home)()+`<footer class="footer">CJAJLK Nature V1.5 · 46 recettes et méthodes · Naturel ne signifie pas sans risque · Données enregistrées localement selon le navigateur.</footer>`+bottom();if(ui.page==='recipes')filterCards();if(ui.page==='guides')filterGuideCards();if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function filterCards(){const cards=[...document.querySelectorAll('#catalog-grid .recipe-card')];let shown=0;cards.forEach(card=>{const r=recipe(card.dataset.id);const visible=(ui.category==='all'||r.category===ui.category)&&norm([r.title,r.desc,r.category,...(r.tags||[])].join(' ')).includes(norm(ui.search))&&(!ui.owned||allOwned(r))&&(!ui.favoritesOnly||state.favorites.includes(r.id));card.classList.toggle('hide',!visible);if(visible)shown++});const el=document.getElementById('results-count');if(el)el.textContent=shown+' recette'+(shown>1?'s':'')+' affichée'+(shown>1?'s':'');document.getElementById('catalog-empty')?.classList.toggle('hide',shown>0);const suggestion=document.getElementById('guide-search-suggestion');if(suggestion){const q=norm(ui.search);const found=q.length>=3?DB.recipes.filter(r=>r.type==='guide'&&norm([r.title,r.desc,...(r.tags||[])].join(' ')).includes(q)):[];suggestion.classList.toggle('hide',!found.length);if(found.length)suggestion.innerHTML=`<div>${icon('info','sm')} <b>Pas une recette, mais un guide disponible</b><p>${found.map(r=>esc(r.title)).join(' · ')}</p></div><button class="btn tiny btn-secondary" data-action="open-guide-search">Lire le conseil ${icon('arrow','sm')}</button>`;}}
let timeoutToast=null;function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(timeoutToast);timeoutToast=setTimeout(()=>el.classList.remove('show'),2900)}
function goto(page,scroll=true){ui.page=page;render(scroll)}
function openRecipe(id){const r=recipe(id);if(!r)return;ui.selectedId=id;ui.quantity=r.base;ui.step=0;ui.safeChecked=false;ui.page='detail';render(true)}
function modal(title,body){document.getElementById('modal-root').innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="small-button" data-modal-action="close" aria-label="Fermer">${icon('close','sm')}</button></div><div class="modal-body">${body}</div></div>`;document.querySelector('#modal-root .modal input:not([type=checkbox]),#modal-root .modal select')?.focus();}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function profileModal(id){const p=state.profiles.find(x=>x.id===id),issues=p?.issues||[];const issueList=[['eczema','Eczéma'],['psoriasis','Psoriasis'],['acne','Acné'],['rougeur','Rougeurs ou irritations'],['lesion','Peau lésée actuellement']];modal(p?'Modifier le profil':'Nouveau profil',`<form id="profile-form" data-id="${esc(id||'')}"><div class="field"><label for="p-name">Prénom ou surnom *</label><input id="p-name" name="name" maxlength="36" required value="${esc(p?.name||'')}"></div><div class="field"><label for="p-skin">Type de peau</label><select id="p-skin" name="skin">${['inconnue','normale','sèche','grasse','mixte','sensible'].map(n=>`<option value="${n}" ${p?.skin===n?'selected':''}>${n[0].toUpperCase()+n.slice(1)}</option>`).join('')}</select></div><div class="field"><span>Problèmes ou sensibilités (facultatif)</span>${issueList.map(([val,label])=>`<label class="checkline"><input type="checkbox" name="issue" value="${val}" ${issues.includes(val)?'checked':''}> ${label}</label>`).join('')}</div><div class="field"><label for="p-allergy">Allergies ou ingrédients à éviter</label><textarea id="p-allergy" name="allergies" placeholder="Ex. : karité, cire d'abeille, avoine (séparer par une virgule)">${esc(p?.allergies||'')}</textarea><span class="field-helper">La détection est indicative : vérifiez toujours tous les ingrédients.</span></div><div class="field"><label for="p-hair">Cheveux / cuir chevelu</label><select id="p-hair" name="hair">${['non précisé','normaux','secs','gras','sensibles'].map(n=>`<option ${p?.hair===n?'selected':''}>${n}</option>`).join('')}</select></div><label class="checkline"><input type="checkbox" name="fragrance" ${p?.fragrance!==false?'checked':''}><span>Je préfère les produits sans parfum.</span></label><p style="margin:12px 0">Ces données sont stockées localement dans ce navigateur. Elles n'établissent aucun diagnostic et ne garantissent aucune compatibilité.</p><div class="modal-actions"><button type="button" class="btn btn-secondary" data-modal-action="close">Annuler</button><button class="btn btn-primary" type="submit">${p?'Enregistrer':'Créer le profil'}</button></div></form>`)}
function stockModal(id){const a=ing(id);if(!a)return;modal('Mettre à jour mon placard',`<form id="stock-form" data-id="${a.id}"><h3 style="margin-bottom:12px">${esc(a.name)}</h3><div class="field"><label for="stock-qty">Quantité actuellement disponible (${a.unit})</label><input id="stock-qty" name="stock" required type="number" min="0" step="0.1" value="${stock(id)}"></div><div class="field"><label for="stock-price">Prix de votre paquet de ${a.pack} ${a.unit} (€)</label><input id="stock-price" name="price" required type="number" min="0" max="10000" step="0.01" value="${pricePack(id)}"></div><p>${esc(a.note)}</p><div class="modal-actions"><button type="button" data-modal-action="close" class="btn btn-secondary">Annuler</button><button class="btn btn-primary" type="submit">Enregistrer</button></div></form>`)}
function finishModal(){const r=recipe(ui.selectedId);if(!r||r.type==='guide')return;const risk=profileRisk(r);if(risk.level==='stop'||risk.level==='setup'||!ui.safeChecked)return toast('Vérifiez le profil et les précautions avant de terminer.');const sc=scaleFor(r);const enough=r.ingredients.every(([id,qty])=>stock(id)+.001>=qty*sc);const cost=recipeCost(r,sc);modal('Enregistrer la fabrication',`<form id="finish-form"><p><b>${esc(r.title)}</b> — ${fmt(ui.quantity)} ${r.yieldUnit}</p><div class="panel slim" style="margin:13px 0"><div class="eyebrow">Coût ingrédients estimé</div><div class="cost-value">${money(cost)}</div></div><div class="field"><label for="comparison">Prix du produit du commerce équivalent pour cette quantité (€), facultatif</label><input id="comparison" name="comparison" type="number" min="0" step="0.01" placeholder="Ex. : 3,50" value="${esc(state.comparisons[r.id]??'')}"><small class="field-helper">Aucune économie n'est calculée sans votre référence.</small></div><label class="checkline"><input name="subtract" type="checkbox" ${enough?'checked':'disabled'}><span>Déduire les quantités utilisées de mon placard ${enough?'':'(stock insuffisant)'}</span></label><p>Enregistrez seulement une préparation effectivement réalisée. Pour une recette à usage immédiat, ne stockez pas les restes.</p><div class="modal-actions"><button class="btn btn-secondary" type="button" data-modal-action="close">Annuler</button><button class="btn btn-primary" type="submit">Enregistrer</button></div></form>`);}
function deleteConfirm(what,id){const isP=what==='profile';modal(isP?'Supprimer le profil ?':'Supprimer la fabrication ?',`<p>Cette suppression efface définitivement ${isP?'les données du profil sélectionné':'cette ligne de votre historique'} du navigateur.</p><div class="modal-actions"><button type="button" class="btn btn-secondary" data-modal-action="close">Annuler</button><button type="button" class="btn btn-danger" data-modal-action="confirm-delete" data-what="${what}" data-id="${id}">Supprimer</button></div>`)}
async function copyText(s){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(s)}else{const el=document.createElement('textarea');el.value=s;document.body.appendChild(el);el.select();document.execCommand('copy');el.remove()}toast('Liste copiée.')}catch(e){modal('Liste à copier',`<textarea style="width:100%;min-height:170px" readonly>${esc(s)}</textarea>`);}}
function exportData(){const payload={app:'CJAJLK Nature',exportedAt:new Date().toISOString(),...state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='CJAJLK_Nature_sauvegarde_'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Sauvegarde téléchargée.');}
function importData(file){if(!file||file.size>2e6)return toast('Fichier absent ou trop volumineux (limite 2 Mo).');const reader=new FileReader();reader.onload=()=>{try{const val=JSON.parse(String(reader.result));if(val.app!=='CJAJLK Nature'||val.version!==1||!Array.isArray(val.profiles)||!Array.isArray(val.batches)||!Array.isArray(val.favorites)||typeof val.inventory!=='object'||typeof val.prices!=='object')throw Error('Format incompatible');if(!confirm('Importer cette sauvegarde et remplacer toutes les données locales actuelles ?'))return;state={...defaultState(),...val};delete state.app;delete state.exportedAt;persist();ui={...ui,page:'home',selectedId:null};render(true);toast('Sauvegarde importée.')}catch(e){toast('Ce fichier n’est pas une sauvegarde CJAJLK Nature V1 valide.')}};reader.readAsText(file)}
// Event delegation: UI uses the same handler on desktop and mobile.
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!document.getElementById('app').contains(b))return;const a=b.dataset.action,id=b.dataset.id;
 switch(a){
 case 'go':goto(b.dataset.page);break;
 case 'go-category':ui.category=b.dataset.category;ui.search='';goto('recipes');break;
 case 'open-guide-search':ui.guideSearch=ui.search;goto('guides');break;
 case 'open-recipe':openRecipe(id);break;
 case 'go-detail':openRecipe(id);break;
 case 'filter':ui.category=b.dataset.category;render();break;
 case 'toggle-owned':ui.owned=!ui.owned;render();break;
 case 'toggle-favorites-filter':ui.favoritesOnly=!ui.favoritesOnly;render();break;
 case 'toggle-fav':state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();render();toast('Favoris mis à jour.');break;
 case 'set-quantity':{const r=recipe(ui.selectedId);ui.quantity=Math.max(1,Math.round(r.base*Number(b.dataset.factor)));ui.step=0;render();break}
 case 'choose-mode':state.mode=b.dataset.mode;persist();ui.step=0;render();break;
 case 'step-next':ui.step=Math.min(recipe(ui.selectedId).steps.length-1,ui.step+1);render();break;
 case 'step-prev':ui.step=Math.max(0,ui.step-1);render();break;
 case 'finish':finishModal();break;
 case 'profile-modal':profileModal(id);break;
 case 'stock-modal':stockModal(id);break;
 case 'select-profile':state.activeProfileId=id;persist();render();toast('Profil actif mis à jour.');break;
 case 'delete-profile':deleteConfirm('profile',id);break;
 case 'delete-batch':deleteConfirm('batch',id);break;
 case 'products-tab':ui.productsTab=b.dataset.tab;render();break;
 case 'copy-equipment':{const r=recipe(ui.selectedId);if(!r||!r.equipment)break;
 const eq=r.equipment;
 copyText('CJAJLK Nature — matériel à prévoir pour '+r.title+'\n\nIndispensable :\n'+eq.essential.map(x=>'• '+x).join('\n')+'\n\nFacultatif :\n'+(eq.optional?.length?eq.optional.map(x=>'• '+x).join('\n'):'Aucun')+'\n\nContenant : '+eq.container+'\n\nPrécaution : '+eq.note+'\n\nLe prix de la recette ne comprend pas le matériel.');break}
 case 'copy-shopping':{const r=recipe(ui.selectedId);const list=missing(r);copyText(list.length?'CJAJLK Nature — ingrédients à acheter pour '+r.title+' ('+fmt(ui.quantity)+' '+r.yieldUnit+')\n'+list.map(([id,n])=>{const a=ing(id);return '• '+a.name+' : '+fmt(Math.max(0,n*scaleFor(r)-stock(id)))+' '+a.unit}).join('\n'):'Tous les ingrédients nécessaires sont disponibles dans votre placard.');break}
 case 'export':exportData();break;
 case 'import':document.getElementById('import-input')?.click();break;
 case 'reset':modal('Effacer mes données ?',`<p>Cette action supprimera vos profils, allergies enregistrées, stocks, prix et historique de ce navigateur. Elle est irréversible sans sauvegarde préalable.</p><div class="modal-actions"><button class="btn btn-secondary" data-modal-action="close">Annuler</button><button class="btn btn-danger" data-modal-action="confirm-reset">Effacer</button></div>`);break;
 }
});
document.getElementById('modal-root').addEventListener('click',e=>{if(e.target.id==='modal-root'){closeModal();return}const b=e.target.closest('[data-modal-action]');if(!b)return;switch(b.dataset.modalAction){case 'close':closeModal();break;case 'confirm-reset':localStorage.removeItem(KEY);state=defaultState();ui={...ui,page:'home',selectedId:null};closeModal();render(true);toast('Données locales effacées.');break;case 'confirm-delete':if(b.dataset.what==='profile'){state.profiles=state.profiles.filter(p=>p.id!==b.dataset.id);if(state.activeProfileId===b.dataset.id)state.activeProfileId=state.profiles[0]?.id||null;}else{state.batches=state.batches.filter(p=>p.id!==b.dataset.id)}persist();closeModal();render();toast('Élément supprimé.');break;}});
document.addEventListener('change',e=>{if(e.target.id==='recipe-qty'){const r=recipe(ui.selectedId),v=Number(e.target.value);if(!Number.isFinite(v)||v<1||v>50000)return toast('Quantité entre 1 et 50 000.');ui.quantity=v;ui.step=0;render();}if(e.target.id==='safety-check'){ui.safeChecked=!!e.target.checked;render();}if(e.target.id==='import-input')importData(e.target.files[0]);});
document.addEventListener('input',e=>{if(e.target.id==='catalog-search'){ui.search=e.target.value;filterCards();}if(e.target.id==='guide-search'){ui.guideSearch=e.target.value;filterGuideCards();}});
document.addEventListener('submit',e=>{if(!['profile-form','stock-form','finish-form'].includes(e.target.id))return;e.preventDefault();const f=e.target,fd=new FormData(f);
 if(f.id==='profile-form'){const name=String(fd.get('name')||'').trim().slice(0,36);if(!name)return toast('Indiquez un prénom ou surnom.');const id=f.dataset.id||('p-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6));const p={id,name,skin:String(fd.get('skin')||'inconnue'),issues:fd.getAll('issue').map(String),allergies:String(fd.get('allergies')||'').trim().slice(0,400),hair:String(fd.get('hair')||''),fragrance:fd.has('fragrance')};const index=state.profiles.findIndex(x=>x.id===id);if(index>=0)state.profiles[index]=p;else state.profiles.push(p);state.activeProfileId=id;persist();closeModal();render();toast('Profil enregistré.');}
 if(f.id==='stock-form'){const id=f.dataset.id,q=Number(fd.get('stock')),price=Number(fd.get('price'));if(!Number.isFinite(q)||q<0||!Number.isFinite(price)||price<0)return toast('Quantités ou prix incorrects.');state.inventory[id]=q;state.prices[id]=price;persist();closeModal();render();toast('Placard mis à jour.');}
 if(f.id==='finish-form'){const r=recipe(ui.selectedId),sc=scaleFor(r),raw=String(fd.get('comparison')||'').trim().replace(',','.');const comp=raw===''?null:Number(raw);if(comp!==null&&(!Number.isFinite(comp)||comp<0))return toast('Prix commerce incorrect.');const batch={id:'b-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),recipeId:r.id,profileId:active()?.id||null,date:new Date().toISOString(),quantity:ui.quantity,unit:r.yieldUnit,cost:recipeCost(r,sc),comparison:comp};state.batches.push(batch);if(state.batches.length>1000)state.batches=state.batches.slice(-1000);if(fd.has('subtract'))r.ingredients.forEach(([id,qty])=>{state.inventory[id]=Math.max(0,stock(id)-qty*sc)});if(comp!==null)state.comparisons[r.id]=comp;persist();closeModal();ui.productsTab='history';goto('products');toast('Fabrication enregistrée !');}
 });
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
render();if('serviceWorker'in navigator&&location.protocol!=='file:'&& (location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'))navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('Mode hors ligne non activé',e));
})();
